    ssl_opts.pem_root_certs = read_file("ca.crt");
    ssl_opts.pem_private_key = read_file("client.key");
    ssl_opts.pem_cert_chain = read_file("client.crt");

    auto creds = grpc::SslCredentials(ssl_opts);
    auto channel = grpc::CreateChannel("api.example.com:443", creds);

    auto stub = MyService::NewStub(channel);

    // Make secure RPC calls
    return 0;
}
```

---

### Example 3: Custom Channel Configuration

```cpp
#include <grpcpp/create_channel.h>
#include <grpcpp/security/credentials.h>
#include <grpcpp/support/channel_arguments.h>

int main() {
    grpc::ChannelArguments args;

    // Large message support
    args.SetMaxReceiveMessageSize(200 * 1024 * 1024);
    args.SetMaxSendMessageSize(200 * 1024 * 1024);

    // Load balancing
    args.SetLoadBalancingPolicyName("round_robin");

    // Compression
    args.SetCompressionAlgorithm(GRPC_COMPRESS_GZIP);

    auto creds = grpc::SslCredentials(grpc::SslCredentialsOptions());
    auto channel = grpc::CreateCustomChannel(
        "backend.example.com:443",
        creds,
        args
    );

    auto stub = MyService::NewStub(channel);

    // Make RPC calls with custom channel settings
    return 0;
}
```

---

### Example 4: Composite Credentials with Custom Metadata

```cpp
#include <grpcpp/create_channel.h>
#include <grpcpp/security/credentials.h>

class AuthPlugin : public grpc::MetadataCredentialsPlugin {
 private:
  std::string api_key_;

 public:
  explicit AuthPlugin(const std::string& key) : api_key_(key) {}

  const char* GetType() const override { return "api_key"; }

  grpc::Status GetMetadata(
      grpc::string_ref /*service_url*/,
      grpc::string_ref /*method_name*/,
      const grpc::AuthContext& /*auth_context*/,
      std::multimap<grpc::string, grpc::string>* metadata) override {
    (*metadata)["x-api-key"] = api_key_;
    return grpc::Status::OK;
  }
};

int main() {
    // Channel-level TLS
    auto ssl_creds = grpc::SslCredentials(grpc::SslCredentialsOptions());

    // Call-level API key
    auto plugin = std::make_unique<AuthPlugin>("my-secret-api-key");
    auto call_creds = grpc::MetadataCredentialsFromPlugin(std::move(plugin));

    // Combine both
    auto composite = grpc::CompositeChannelCredentials(ssl_creds, call_creds);

    auto channel = grpc::CreateChannel("api.example.com:443", composite);
    auto stub = MyService::NewStub(channel);

    return 0;
}
```

---

## Error Handling

When credentials are invalid or cannot be created, `CreateChannel` and `CreateCustomChannel` return a valid channel pointer, but the channel is "lame" — all RPC operations will fail.

```cpp
auto invalid_creds = grpc::SslCredentials(
    grpc::SslCredentialsOptions()  // Invalid/empty options
);
auto channel = grpc::CreateChannel("example.com:443", invalid_creds);

// All RPCs on this channel will fail
// Check for errors in RPC Status objects
```

---

## Best Practices

1. **Reuse Channels**: Create channels once and reuse them for multiple stubs and RPCs.
   ```cpp
   auto channel = grpc::CreateChannel(target, creds);
   auto stub1 = Service1::NewStub(channel);
   auto stub2 = Service2::NewStub(channel);
   ```

2. **Use Appropriate Credentials**:
   - Development/Testing: `InsecureChannelCredentials()`
   - Production: `SslCredentials()` with proper certificates
   - Google Cloud: `GoogleDefaultCredentials()`

3. **Configure Message Sizes for Your Use Case**:
   ```cpp
   args.SetMaxReceiveMessageSize(100 * 1024 * 1024);  // 100 MB
   args.SetMaxSendMessageSize(100 * 1024 * 1024);
   ```

4. **Enable Compression for Large Messages**:
   ```cpp
   args.SetCompressionAlgorithm(GRPC_COMPRESS_GZIP);
   ```

5. **Use Composite Credentials for Mixed Authentication**:
   ```cpp
   auto composite = grpc::CompositeChannelCredentials(channel_creds, call_creds);
   ```

6. **Handle Credential Creation Failures**:
   Even if credentials appear to fail, the channel is created. Errors manifest in RPC Status objects.

---

## References

- [gRPC Authentication Guide](https://grpc.io/docs/guides/auth.html)
- [gRPC C++ API Reference](https://grpc.io/docs/languages/cpp/)
- [gRPC Channel Arguments](https://github.com/grpc/grpc/blob/master/doc/channel_args.md)
- Header Files:
  - `include/grpcpp/create_channel.h`
  - `include/grpcpp/security/credentials.h`
  - `include/grpcpp/support/channel_arguments.h`

